// the Maybe?, Not Now and Done columns to change their status. Columns keep
// their own order: a card is moved between columns, never within one.
//
// The board is updated the moment the card is dropped, without waiting for the
// change to be saved, so it already looks the way you left it when you let go.
const DRAGGED_ITEM_CLASS = "drag-and-drop__dragged-item"
const HOVER_CONTAINER_CLASS = "drag-and-drop__hover-container"
const COLUMN_SELECTOR = '[data-drag-and-drop-target~="column"]'
const CARD_SELECTOR = ".card"
const CARD_LIST_SELECTOR = ".cards__list"
const COLUMN_COUNT_SELECTOR = ".cards__expander-count"
const CURRENT_COLUMN_SELECTOR = ".card__column-name--current"
const GOLDEN_EFFECT_CLASS = "golden-effect"
const POSTPONED_CLASS = "card--postponed"
const STREAM_DESTINATION = "stream"
const COLUMN_DESTINATION = "column"
const DRAG_THRESHOLD = 5

export default class extends Controller {
  static targets = [ "card" ]

  initialize() {
    this.#trackPointer = this.#trackPointer.bind(this)
    this.#releasePointer = this.#releasePointer.bind(this)
  }

  connect() {
    this.draggedCard = null
    this.hoveredColumn = null
    this.pointer = null
  }

  disconnect() {
    this.#endDrag()
  }

  dragStarted(event) {
    const card = this.#cardFrom(event)
    if (!card) return

    event.preventDefault() // Dragging is handled with the pointer, the browser shouldn't drag cards around itself
    this.#startDragging(card)
  }

  draggedOver(event) {
    if (!this.isDragging) return

    event.preventDefault()
    this.#hoverColumn(this.#columnFrom(event))
  }

  dragLeft(event) {
    if (!this.isDragging) return
    if (this.element.contains(event.relatedTarget)) return

    this.#hoverColumn(null)
  }

  dropped(event) {
    if (!this.isDragging) return

    event.preventDefault()
    this.#drop(this.#columnFrom(event))
  }

  dragEnded() {
    this.#endDrag()
  }

  pointerDown(event) {
    if (event.pointerType !== "mouse" || event.button !== 0) return

    const card = this.#cardFrom(event)
    if (!card) return

    this.pointer = { card, x: event.clientX, y: event.clientY }
    this.#listenForPointer()
  }

  // Private

  #trackPointer(event) {
    if (!this.pointer) return

    if (this.isDragging) {
      event.preventDefault()
      this.#hoverColumn(this.#columnFrom(event))
    } else if (this.#isPastDragThreshold(event)) {
      this.#startDragging(this.pointer.card)
    }
  }

  #releasePointer(event) {
    if (!this.pointer) return

    const column = this.#columnFrom(event)
    this.#forgetPointer()
    this.#drop(column)
  }
  ...
